messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>

<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TRACK_LENGTH = 100;
    const FINISH_LINE_Z = -50;
    const START_Z = 50;
    const CAR_WIDTH = 2.2;
    const CAR_LENGTH = 4.5;
    const CAR_HEIGHT = 1.8;

    // Animation Timing
    const BLUE_LEAD_DURATION = 2.0; // seconds blue stays ahead
    const OVERTAKE_START = 2.0;
    const OVERTAKE_END = 3.5;
    const TOTAL_CYCLE = 6.0; // seconds for full race loop

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 20, 80);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
    camera.position.set(0, 12, 20);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(10, 20, 10);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 100;
    dirLight.shadow.camera.left = -20;
    dirLight.shadow.camera.right = 20;
    dirLight.shadow.camera.top = 20;
    dirLight.shadow.camera.bottom = -20;
    scene.add(dirLight);

    // --- Environment ---
    // Ground
    const groundGeo = new THREE.PlaneGeometry(200, 200);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x228b22 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(20, 2);
    const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.z = FINISH_LINE_Z;
    finishLine.position.y = 0.05;
    scene.add(finishLine);

    // Finish Line Posts
    const postGeo = new THREE.BoxGeometry(0.5, 4, 0.5);
    const postMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const leftPost = new THREE.Mesh(postGeo, postMat);
    leftPost.position.set(-10, 2, FINISH_LINE_Z);
    scene.add(leftPost);
    const rightPost = new THREE.Mesh(postGeo, postMat);
    rightPost.position.set(10, 2, FINISH_LINE_Z);
    scene.add(rightPost);

    // --- Car Class ---
    class Car {
        constructor(color, xOffset) {
            this.group = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(CAR_WIDTH, 1.2, CAR_LENGTH);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            this.chassis = new THREE.Mesh(chassisGeo, chassisMat);
            this.chassis.position.y = 0.6;
            this.chassis.castShadow = true;
            this.group.add(this.chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(CAR_WIDTH - 0.5, 1, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            this.cabin = new THREE.Mesh(cabinGeo, cabinMat);
            this.cabin.position.set(0, 1.5, -0.2);
            this.cabin.castShadow = true;
            this.group.add(this.cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheelPositions = [
                { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 },
                { x: -1.1, z: -1.2 }, { x: 1.1, z: -1.2 }
            ];
            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.6, pos.z);
                this.group.add(wheel);
            });

            this.group.position.set(xOffset, 0, START_Z);
            scene.add(this.group);
        }

        update(t) {
            // Basic bounce effect
            this.group.position.y = Math.sin(t * 10) * 0.1;
        }
    }

    const redCar = new Car(0xff0000, -3.5);
    const blueCar = new Car(0x0000ff, 3.5);

    // --- Animation Loop ---
    let startTime = Date.now();

    function animate() {
        requestAnimationFrame(animate);

        const currentTime = (Date.now() - startTime) / 1000;
        // Loop time within TOTAL_CYCLE
        const loopTime = currentTime % TOTAL_CYCLE;

        // --- Race Logic ---

        // 1. Reset Phase (0s to 0.5s): Both at start
        // 2. Blue Lead Phase (0.5s to 2.0s): Blue moves fast, Red moves slow
        // 3. Overtake Phase (2.0s to 3.5s): Red accelerates past Blue
        // 4. Win Phase (3.5s to 6.0s): Red crosses finish, resets

        let redZ = START_Z;
        let blueZ = START_Z;

        if (loopTime < 0.5) {
            // Reset: Cars stay at start
            redZ = START_Z;
            blueZ = START_Z;
        } else if (loopTime < 2.0) {
            // Blue leads
            const t = (loopTime - 0.5) / 1.5; // 0 to 1
            redZ = START_Z - (20 * t); // Red moves slower
            blueZ = START_Z - (40 * t); // Blue moves faster
        } else if (loopTime < 3.5) {
            // Red overtakes
            const t = (loopTime - 2.0) / 1.5; // 0 to 1

            // Red accelerates
            redZ = START_Z - 20 - (30 * t); 
            // Blue slows down slightly
            blueZ = START_Z - 40 - (10 * t);
        } else if (loopTime < 4.5) {
            // Red wins / crosses finish
            const t = (loopTime - 3.5) / 1.0;
            redZ = FINISH_LINE_Z - (5 * t);
            blueZ = FINISH_LINE_Z - (2 * t);
        } else {
            // Reset to start for next loop
            redZ = START_Z;
            blueZ = START_Z;
        }

        // Update positions
        redCar.group.position.z = redZ;
        blueCar.group.position.z = blueZ;

        // Update simple physics animations
        redCar.update(currentTime);
        blueCar.update(currentTime);

        // --- Camera Logic ---
        // Camera follows the Red car (the winner) but keeps Blue in view
        // We interpolate camera position based on Red car's Z

        const lookAhead = 15;
        camera.position.x = -4; // Slightly offset to see both
        camera.position.y = 8;
        camera.position.z = redZ - lookAhead;

        // Look at a point between the two cars
        const midZ = (redZ + blueZ) / 2;
        camera.lookAt(midZ, 0, 0); // Look slightly ahead

        // Update directional light to follow cars
        dirLight.position.z = redZ;
        dirLight.target.position.z = redZ;
        dirLight.updateMatrixWorld();

        renderer.render(scene, camera);
    }

    // Handle resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>

</body>
</html>
```
